<div class="welcome"><div><h2><?=__('Ringkasan operasional')?></h2><p><?=__('Status inventaris dan pekerjaan tim hari ini.')?></p></div><a class="btn primary" href="/tugas/create"><?=__('Buat tugas')?></a></div>
<div class="stats"><a class="stat" href="/pc"><span class="stat-icon green"><?=simit_icon('pc')?></span><div><small><?=__('Total PC')?></small><strong><?=$stats['pc']?></strong><em><?=__('aset aktif')?></em></div></a><a class="stat" href="/pc?q=servis"><span class="stat-icon amber"><?=simit_icon('pemeriksaan')?></span><div><small><?=__('Perlu perhatian')?></small><strong><?=$stats['problem']?></strong><em><?=__('perangkat')?></em></div></a><a class="stat" href="/perangkat"><span class="stat-icon blue"><?=simit_icon('perangkat')?></span><div><small><?=__('Perangkat lain')?></small><strong><?=$stats['units']?></strong><em><?=__('total unit')?></em></div></a><a class="stat" href="/tugas"><span class="stat-icon purple"><?=simit_icon('tugas')?></span><div><small><?=__('Tugas terbuka')?></small><strong><?=$stats['open_tasks']?></strong><em><?=__('perlu tindak lanjut')?></em></div></a></div>
<style>.task-row.clickable,.attention.clickable{cursor:pointer;border-radius:12px;transition:.18s ease}.task-row.clickable:hover,.attention.clickable:hover{background:rgba(37,131,59,.07);transform:translateX(3px)}</style><script>document.addEventListener('DOMContentLoaded',()=>{const taskIds=<?=json_encode(array_column($tasks,'id'))?>;document.querySelectorAll('.task-row').forEach((row,i)=>{row.classList.add('clickable');row.tabIndex=0;const go=()=>location.href='/tugas/hasil/'+taskIds[i];row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}})});const attention=<?=json_encode(array_map(fn($a)=>['id'=>$a['id'],'type'=>$a['type']],$attention))?>;document.querySelectorAll('.attention').forEach((row,i)=>{row.classList.add('clickable');row.tabIndex=0;const go=()=>location.href='/'+(attention[i].type==='PC'?'pc':'perangkat')+'/edit/'+attention[i].id;row.addEventListener('click',go);row.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();go()}})})});</script>
<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3><?=__('Tugas prioritas')?></h3><p><?=__('Pekerjaan yang perlu segera ditindaklanjuti.')?></p></div><a href="/tugas"><?=__('Lihat semua')?></a></div><div class="task-list"><?php foreach($tasks as $t):?><article class="task-row"><span class="priority <?=strtolower($t['priority'])?>"></span><div><strong><?=e($t['title'])?></strong><small><?=e($t['number'])?> · <?=e($t['assignee']?:__('Belum ada PIC'))?></small></div><span class="badge"><?=e(__($t['status']))?></span></article><?php endforeach;?><?php if(!$tasks):?><div class="empty"><?=__('Tidak ada tugas terbuka.')?></div><?php endif;?></div></section><section class="panel"><div class="panel-head"><div><h3><?=__('Perlu perhatian')?></h3><p><?=__('Temuan kondisi perangkat terbaru.')?></p></div><a href="/perangkat"><?=__('Tinjau')?></a></div><?php if($attention):foreach($attention as $a):?><article class="attention"><span class="stat-icon amber"><?=simit_icon('pemeriksaan')?></span><div><strong><?=e($a['name'])?></strong><small><?=e($a['location']??'-')?> · <?=e($a['notes']??__('Tanpa catatan'))?></small></div><span class="badge danger"><?=e(__($a['status']))?></span></article><?php endforeach;else:?><div class="healthy"><span><?=simit_icon('audit')?></span><strong><?=__('Semua perangkat terpantau')?></strong><p><?=__('Belum ada perangkat berstatus rusak atau perlu servis.')?></p></div><?php endif;?></section></div>

